theorem MeasureTheory.ProbabilityMeasure.extracted_1.{u_2, u_1} {α : Type u_1} [inst : MeasurableSpace α] {β : Type u_2}
  [inst_1 : MeasurableSpace β] (μ : ProbabilityMeasure α) (ν : ProbabilityMeasure β) {s : Set (α × β)}
  (hs : MeasurableSet s) (h : (fun x => ν (Prod.mk x ⁻¹' s)) =ᶠ[ae ↑μ] 0) (p : α) (hp : ν (Prod.mk p ⁻¹' s) = 0)
  (con : ↑ν (Prod.mk p ⁻¹' s) = ⊤) : ↑ν (Prod.mk p ⁻¹' s) = 0 := by
  by_contra
          exact measure_ne_top _ _ con

theorem MeasureTheory.ProbabilityMeasure.extracted_1.{u_2, u_1} {α : Type u_1} [inst : MeasurableSpace α] {β : Type u_2}
  [inst_1 : MeasurableSpace β] (μ : ProbabilityMeasure α) (ν : ProbabilityMeasure β) {s : Set (α × β)}
  (hs : MeasurableSet s) (h : (fun x => ν (Prod.mk x ⁻¹' s)) =ᶠ[ae ↑μ] 0) (p : α) (hp : ν (Prod.mk p ⁻¹' s) = 0)
  (h' : ↑ν (Prod.mk p ⁻¹' s) = 0) : ↑ν (Prod.mk p ⁻¹' s) = 0 := by
  exact h'

theorem MeasureTheory.ProbabilityMeasure.extracted_1.{u_2, u_1} {α : Type u_1} [inst : MeasurableSpace α] {β : Type u_2}
  [inst_1 : MeasurableSpace β] (μ : ProbabilityMeasure α) (ν : ProbabilityMeasure β) {s : Set (α × β)}
  (hs : MeasurableSet s) : (μ.prod ν) s = 0 ↔ ((↑μ).prod ↑ν) s = 0 := by
  simp

theorem MeasureTheory.ProbabilityMeasure.extracted_1.{u_2, u_1} {α : Type u_1} [inst : MeasurableSpace α] {β : Type u_2}
  [inst_1 : MeasurableSpace β] (μ : ProbabilityMeasure α) (ν : ProbabilityMeasure β) {s : Set (α × β)}
  (h : (μ.prod ν) s = 0) : ((↑μ).prod ↑ν) s = 0 := by
  simpa [toNNReal_eq_zero_iff] using h
